export default function JoseSanchezDelRio({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1024"
          height="1536"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open background area behind the saint and card scene. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1024" height="1536" />
        </g>

        {/* Left and right cloud banks. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Halo field behind the head. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Jacket / outer garment and sleeve shapes. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Inner shirt and lower clothing forms. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, ears, neck, and both hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Curly hair and eyebrows. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Palm branch, cross, belt/strap, and related accessory details. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Banner, Our Lady image, lock badge, church/flag, cactus, and scene details. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied José Sánchez del Río image.
            Keep this last and non-interactive so every region remains paintable. */}
        <path
          {...detail}
          {...ink}
          d={JOSE_SANCHEZ_DEL_RIO_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}